<div class="bot-block"><div class="bot-header"></div><div class="bot-header-mes"><el-progress style="position:relative;margin-bottom: 4px;" :percentage="getLifeNow(props.allMes.allMesBot.playerNow)" :text-inside="true" :stroke-width="6" color="#ffe3e3"></el-progress><div class="bot-header-power" v-for="(power,index) in powerList"><div class="bot-header-power-light" v-if="index&lt;props.allMes.allMesBot.playerNow.power"></div></div></div><div class="bot-life"><el-progress style="position:relative;" :percentage="getLifeNow(props.allMes.allMesBot.monsterNow)" :text-inside="true" :stroke-width="16" color="#ffe3e3"><div class="progress-position">{{props.allMes.allMesBot.monsterNow.lifeNow}}</div></el-progress><div class="card-list"><div class="hand-one" v-for="hand in props.allMes.allMesBot.handCardList" :style="'width:'+400/props.allMes.allMesBot.handCardList.length + 'px;'"><div class="hand-one-img"></div></div></div><div class="card-num">{{props.allMes.allMesBot.handCardList.length}}</div></div></div>